#!/usr/bin/env node
/**
 * Bundle size analysis — tracks size over time, fails on >10% increase, visualizes chunks.
 * Usage: node scripts/bundle-analysis.mjs [--update-baseline] [--threshold 10]
 *
 * - Reads dist/ sizes after vite build
 * - Compares against .bundle-baseline.json (committed)
 * - Fails if any chunk grows > threshold % (default 10%)
 * - Generates bundle-report.json and bundle-report.md for CI artifacts
 * - Visualizes via stats.html (generated by rollup-plugin-visualizer)
 */

import { promises as fs } from 'node:fs'
import { join, basename } from 'node:path'
import { gzipSync, brotliCompressSync } from 'node:zlib'

const DIST = 'dist'
const BASELINE_FILE = '.bundle-baseline.json'
const REPORT_JSON = 'bundle-report.json'
const REPORT_MD = 'bundle-report.md'
const THRESHOLD = Number(process.argv.find((_, i, a) => a[i - 1] === '--threshold') || 10)
const UPDATE_BASELINE = process.argv.includes('--update-baseline')

async function getFiles(dir, pattern = /.*/) {
  const entries = []
  async function walk(d) {
    const items = await fs.readdir(d, { withFileTypes: true })
    for (const it of items) {
      const p = join(d, it.name)
      if (it.isDirectory()) await walk(p)
      else if (pattern.test(p)) entries.push(p)
    }
  }
  try {
    await walk(dir)
  } catch {
    return []
  }
  return entries
}

function formatBytes(bytes) {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} kB`
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`
}

async function analyze() {
  const jsFiles = await getFiles(DIST, /\.js$/)
  const cssFiles = await getFiles(DIST, /\.css$/)
  const htmlFiles = await getFiles(DIST, /\.html$/)
  const allFiles = [...jsFiles, ...cssFiles, ...htmlFiles]

  if (allFiles.length === 0) {
    console.error('❌ No dist files found. Run `npm run build` first.')
    process.exit(1)
  }

  const chunks = []
  let totalRaw = 0
  let totalGzip = 0
  let totalBrotli = 0

  for (const file of allFiles) {
    const buf = await fs.readFile(file)
    const raw = buf.length
    const gz = gzipSync(buf).length
    const br = (() => {
      try { return brotliCompressSync(buf).length } catch { return gz }
    })()
    totalRaw += raw
    totalGzip += gz
    totalBrotli += br

    // Only track JS chunks individually; CSS/HTML aggregated
    if (file.endsWith('.js')) {
      const name = basename(file)
      let category = 'other'
      if (name.includes('feature-three')) category = 'feature-three'
      else if (name.includes('feature-stellar')) category = 'feature-stellar'
      else if (name.includes('react-vendor')) category = 'react-vendor'
      else if (name.includes('vendor')) category = 'vendor'
      else if (name.includes('index')) category = 'main'
      chunks.push({ file: file.replace(`${DIST}/`, ''), name, category, raw, gzip: gz, brotli: br })
    }
  }

  // Also track CSS/HTML totals
  let cssRaw = 0, cssGz = 0
  for (const f of cssFiles) {
    const b = await fs.readFile(f)
    cssRaw += b.length
    cssGz += gzipSync(b).length
  }

  const summary = {
    timestamp: new Date().toISOString(),
    total: { raw: totalRaw, gzip: totalGzip, brotli: totalBrotli, formatted: { raw: formatBytes(totalRaw), gzip: formatBytes(totalGzip), brotli: formatBytes(totalBrotli) } },
    css: { raw: cssRaw, gzip: cssGz, formatted: { raw: formatBytes(cssRaw), gzip: formatBytes(cssGz) } },
    chunks: chunks.sort((a, b) => b.gzip - a.gzip),
  }

  // Check stats.html exists (bundle visualization)
  let hasVisualization = false
  try { await fs.access('stats.html'); hasVisualization = true } catch {}
  let hasStatsJson = false
  try { await fs.access('stats.json'); hasStatsJson = true } catch {}

  summary.visualization = { html: hasVisualization ? 'stats.html' : null, json: hasStatsJson ? 'stats.json' : null }

  console.log('\n📦 Bundle Analysis')
  console.log('─────────────────────────────────────────')
  for (const c of summary.chunks) {
    console.log(`  ${c.category.padEnd(16)} ${c.name.slice(0, 32).padEnd(34)} raw=${formatBytes(c.raw).padStart(9)} gzip=${formatBytes(c.gzip).padStart(9)} brotli=${formatBytes(c.brotli).padStart(9)}`)
  }
  console.log('─────────────────────────────────────────')
  console.log(`  TOTAL                raw=${formatBytes(totalRaw).padStart(9)} gzip=${formatBytes(totalGzip).padStart(9)} brotli=${formatBytes(totalBrotli).padStart(9)}`)
  console.log(`  CSS                  raw=${formatBytes(cssRaw).padStart(9)} gzip=${formatBytes(cssGz).padStart(9)}`)
  console.log(`  Visualization: ${hasVisualization ? '✅ stats.html' : '❌ missing stats.html'} ${hasStatsJson ? '✅ stats.json' : ''}`)
  console.log('')

  // Load baseline
  let baseline = null
  try {
    const raw = await fs.readFile(BASELINE_FILE, 'utf8')
    baseline = JSON.parse(raw)
  } catch {
    console.warn(`⚠️  No baseline found at ${BASELINE_FILE}. Creating one...`)
  }

  const failures = []
  const warnings = []
  let reportMd = `# 📦 Bundle Report — ${new Date().toISOString().slice(0, 10)}\n\n`
  reportMd += `| Chunk | Category | Raw | Gzip | Brotli | vs Baseline (gzip) |\n`
  reportMd += `|-------|----------|-----|------|--------|--------------------|\n`

  for (const chunk of summary.chunks) {
    let delta = null
    let deltaPct = null
    let status = '—'
    if (baseline) {
      const baseChunk = baseline.chunks?.find((b) => b.category === chunk.category && b.name.split('-')[0] === chunk.name.split('-')[0])
        || baseline.chunks?.find((b) => b.category === chunk.category)
      if (baseChunk) {
        delta = chunk.gzip - baseChunk.gzip
        deltaPct = baseChunk.gzip > 0 ? (delta / baseChunk.gzip) * 100 : 0
        if (deltaPct > THRESHOLD) {
          status = `🔴 +${deltaPct.toFixed(1)}% (+${formatBytes(delta)})`
          failures.push({ chunk: chunk.name, category: chunk.category, deltaPct, delta, current: chunk.gzip, baseline: baseChunk.gzip })
        } else if (deltaPct > THRESHOLD * 0.6) {
          status = `🟡 +${deltaPct.toFixed(1)}%`
          warnings.push(chunk.name)
        } else if (deltaPct < -5) {
          status = `🟢 ${deltaPct.toFixed(1)}% (${formatBytes(delta)})`
        } else {
          status = `${deltaPct >= 0 ? '+' : ''}${deltaPct.toFixed(1)}%`
        }
      } else {
        status = 'new chunk'
      }
    } else {
      status = 'no baseline'
    }
    reportMd += `| \`${chunk.name}\` | ${chunk.category} | ${formatBytes(chunk.raw)} | ${formatBytes(chunk.gzip)} | ${formatBytes(chunk.brotli)} | ${status} |\n`
  }
  // Totals row
  if (baseline?.total?.gzip) {
    const totDelta = summary.total.gzip - baseline.total.gzip
    const totPct = (totDelta / baseline.total.gzip) * 100
    let totStatus = `${totPct >= 0 ? '+' : ''}${totPct.toFixed(1)}%`
    if (totPct > THRESHOLD) {
      totStatus = `🔴 +${totPct.toFixed(1)}%`
      failures.push({ chunk: 'TOTAL', category: 'total', deltaPct: totPct, delta: totDelta, current: summary.total.gzip, baseline: baseline.total.gzip })
    } else if (totPct > THRESHOLD * 0.6) totStatus = `🟡 +${totPct.toFixed(1)}%`
    else if (totPct < -5) totStatus = `🟢 ${totPct.toFixed(1)}%`
    reportMd += `| **TOTAL** | total | ${formatBytes(totalRaw)} | ${formatBytes(totalGzip)} | ${formatBytes(totalBrotli)} | ${totStatus} |\n`
  } else {
    reportMd += `| **TOTAL** | total | ${formatBytes(totalRaw)} | ${formatBytes(totalGzip)} | ${formatBytes(totalBrotli)} | no baseline |\n`
  }

  reportMd += `\n**Threshold:** fail on >${THRESHOLD}% gzip increase per chunk / total\n`
  reportMd += `**Visualization:** ${hasVisualization ? '[\`stats.html\`](./stats.html)' : 'missing — run build with visualizer'} ${hasStatsJson ? '+ `stats.json`' : ''}\n`
  if (failures.length) {
    reportMd += `\n### ❌ Failures (${failures.length})\n`
    for (const f of failures) reportMd += `- \`${f.chunk}\` (${f.category}) grew **+${f.deltaPct.toFixed(1)}%** (+${formatBytes(f.delta)}) — baseline ${formatBytes(f.baseline)} → ${formatBytes(f.current)}\n`
  }
  if (warnings.length) reportMd += `\n### ⚠️ Warnings: ${warnings.join(', ')} near threshold\n`
  if (!failures.length) reportMd += `\n✅ All chunks within ${THRESHOLD}% budget\n`

  // Write reports
  await fs.writeFile(REPORT_JSON, JSON.stringify(summary, null, 2))
  await fs.writeFile(REPORT_MD, reportMd)
  console.log(`📝 Reports written: ${REPORT_JSON}, ${REPORT_MD}`)

  // Update baseline if requested or if no baseline
  if (UPDATE_BASELINE || !baseline) {
    await fs.writeFile(BASELINE_FILE, JSON.stringify(summary, null, 2))
    console.log(`📌 Baseline ${UPDATE_BASELINE ? 'updated' : 'created'} at ${BASELINE_FILE}`)
    // Don't fail when updating
    if (!baseline) {
      console.log('ℹ️  Initial baseline — no comparison failure')
      return
    }
  }

  if (failures.length) {
    console.error(`\n❌ Bundle size check FAILED: ${failures.length} chunk(s) exceeded +${THRESHOLD}% threshold`)
    for (const f of failures) console.error(`   - ${f.chunk} (${f.category}): +${f.deltaPct.toFixed(1)}%`)
    console.error(`\nTo update baseline after intentional growth: npm run bundle:update-baseline\n`)
    process.exit(1)
  } else {
    console.log(`\n✅ Bundle size check passed (threshold +${THRESHOLD}% gzip)`)
  }

  // Also check size-limit budgets (quick)
  try {
    const sizeLimit = JSON.parse(await fs.readFile('.size-limit.json', 'utf8'))
    console.log('\n📏 Size-limit budgets:')
    for (const entry of sizeLimit) {
      console.log(`  - ${entry.name || entry.path}: limit ${entry.limit}${entry.gzip ? ' (gzip)' : ''}`)
    }
  } catch {}
}

analyze().catch((e) => { console.error(e); process.exit(1) })
